/* Q&A library for non-VA loan types — FHA, conventional, USDA, jumbo, Non-QM, DSCR, foreign national/ITIN, reverse, HELOC, construction, renovation,
   manufactured, DPA, refinance, credit & process. Shape: {prog, cat, q, a, ref}. */
const LQ=(prog,cat,q,a,ref)=>({prog,cat,q,a,ref});
const LOAN_QA=[
// ===== FHA =====
LQ("FHA","Basics","What is an FHA loan and who is it for?","A mortgage insured by the Federal Housing Administration (HUD) that lets lenders accept 3.5% down and lower credit scores. It is for owner-occupied 1–4 unit homes and suits buyers with limited savings, scores in the 580–680 range, higher DTI, or recent credit events. The cost is mortgage insurance: 1.75% upfront and an annual premium (0.15%–0.75% depending on LTV, term and amount) that lasts the life of the loan when down payment is under 10%.","HUD Handbook 4000.1 II.A"),
LQ("FHA","Basics","What's the minimum credit score for FHA?","580 for 3.5% down; 500–579 with 10% down. Lenders commonly overlay to 600–640. Borrowers with no score can qualify with non-traditional credit on a manual underwrite.","4000.1 II.A.1.b.ii(A)"),
LQ("FHA","Basics","How much is the FHA down payment?","3.5% of the lesser of the price or appraised value (the 'minimum required investment'), which can come from gifts, DPA or grants—not from the seller or anyone with an interest in the sale.","4000.1 II.A.2.b"),
LQ("FHA","MIP","How does FHA mortgage insurance work?","Upfront MIP of 1.75% is financed; annual MIP (paid monthly) is 0.55% for most 30-year loans ≥95% LTV and ≤$726,200 (0.50% for ≤95% LTV; lower for 15-year terms; higher above the base loan limit). It lasts 11 years if the original LTV was ≤90%, otherwise for the life of the loan—so most FHA borrowers refinance to conventional once they reach 20% equity.","4000.1 Appendix 1.0; ML 2023-05"),
LQ("FHA","MIP","Can FHA MIP be cancelled?","Not by request. Only loans with ≥10% down (≤90% LTV) drop MIP after 11 years. The exit is a conventional refinance at 80% LTV or less (or 78% automatic cancellation rules on conventional).","4000.1 Appendix 1.0"),
LQ("FHA","MIP","Do I get the upfront MIP back if I refinance?","If you refinance FHA-to-FHA (streamline or otherwise) within 3 years, a declining portion of the upfront premium is credited toward the new UFMIP (starts ~80% in month 1, declines to 0 at 36 months).","4000.1 II.A.8.d; UFMIP refund schedule"),
LQ("FHA","Limits","What are the FHA loan limits for 2026?","Floor $541,288 and ceiling $1,249,125 for 1-unit (high-cost counties like LA/Orange at the ceiling; San Diego $1,077,550—verify); higher for 2–4 units. Limits follow 65%/150% of the conforming baseline.","HUD ML 2025-xx (2026 limits); FHFA"),
LQ("FHA","Ratios","What DTI does FHA allow?","Manual underwriting: 31/43 (front/back), up to 37/47 with one compensating factor and 40/50 with two. TOTAL Scorecard Approve/Eligible: commonly up to 46.99/56.99.","4000.1 II.A.5.d"),
LQ("FHA","Ratios","What are FHA compensating factors for manual underwrites?","Verified cash reserves (3+ months), minimal payment shock (new payment ≤5% increase or ≤$100), residual income meeting VA tables, additional income not used for qualifying, and no discretionary debt.","4000.1 II.A.5.d.viii"),
LQ("FHA","Credit","How long after bankruptcy or foreclosure for FHA?","Chapter 7: 2 years from discharge (12 months with documented extenuating circumstances and re-established credit). Chapter 13: 12 months of on-time plan payments with court/trustee permission. Foreclosure/DIL: 3 years from the date title transferred; short sale: 3 years (less if payments were current and extenuating circumstances).","4000.1 II.A.5.a.iii"),
LQ("FHA","Credit","How does FHA treat collections and judgments?","Medical collections are ignored. Non-medical collections totaling more than $2,000 must be paid, in a payment plan, or 5% of the outstanding balance is added to monthly debts. Judgments must be paid or have a payment plan with 3 months of payments.","4000.1 II.A.4.b.iv(I)/(J) and II.A.5.a.iii"),
LQ("FHA","Credit","Are disputed accounts a problem on FHA?","Disputed derogatory accounts with an aggregate balance over $1,000 trigger a manual underwrite (downgrade from TOTAL) unless resolved; non-derogatory disputes don't.","4000.1 II.A.4.b.iv(F)"),
LQ("FHA","Credit","Does a federal tax lien stop an FHA loan?","It must be paid or the borrower must have an IRS repayment plan with at least 3 months of payments made and the lien subordinated/not affecting first-lien position.","4000.1 II.A.5.a.iii(J)"),
LQ("FHA","Credit","Can I get FHA with no credit score?","Yes via non-traditional credit (12 months of rent plus 2 other sources such as utilities, insurance, phone) on a manual underwrite; ratios limited to 31/43 unless compensating factors.","4000.1 II.A.4.b.iii & II.A.5"),
LQ("FHA","Income","How does FHA count student loans?","If deferred or on IBR: the greater of the documented payment or 0.5% of the outstanding balance (if the documented payment is $0 or no payment is shown, use 0.5%).","4000.1 II.A.4.b.iv(H); ML 2021-13"),
LQ("FHA","Income","Can I use a non-occupant co-borrower on FHA?","Yes. Family members can co-borrow without living in the home at the full 96.5% LTV on 1-unit (and 2-unit?—verify: 1-unit only at 96.5%; otherwise 75% LTV). Unrelated non-occupant co-borrowers limit LTV to 75%.","4000.1 II.A.2.b.iv(B)"),
LQ("FHA","Income","How is self-employed income verified for FHA?","Two years of business and personal returns, YTD P&L and balance sheet, and 2–3 months business statements; one year is acceptable with 2+ years in a similar occupation; declining income >20% triggers a stability review.","4000.1 II.A.4.c.xi / II.A.5.b.x"),
LQ("FHA","Income","Can rental income from the home I'm buying count (2–4 units)?","Yes: 75% of the appraiser's market rents or current leases on the non-owner units. For 3–4 units the property must pass the self-sufficiency test (75% of total rents ≥ PITIA).","4000.1 II.A.4.c.xii"),
LQ("FHA","Assets","Who can give me gift funds on FHA?","Family members (including domestic partners and close friends with a documented interest), employers, labor unions, charities, and government agencies. Not the seller, builder, agent or anyone with an interest in the transaction (except via approved DPA).","4000.1 II.A.4.d.iii"),
LQ("FHA","Assets","What is a 'large deposit' on FHA?","Any single deposit over 1% of the adjusted value must be explained and sourced.","4000.1 II.A.4.d.iii(A)"),
LQ("FHA","Assets","Does FHA require reserves?","Manual underwrites: 1 month PITI for 1–2 units, 3 months for 3–4 units. TOTAL approvals: none for 1–2 units; 3 months for 3–4 units.","4000.1 II.A.5.b.ix"),
LQ("FHA","Seller credits","How much can the seller pay on FHA?","Up to 6% of the price toward closing costs, prepaids, discount points, UFMIP and temporary buydowns. Anything beyond 6% is treated as an inducement to purchase and reduces the value for LTV. The seller may never pay the 3.5% down payment.","4000.1 II.A.4.d.i"),
LQ("FHA","Property","What are FHA property standards?","Minimum Property Requirements (safety, security, soundness) and Minimum Property Standards for new construction: working systems, roof with 2+ years life, no peeling paint (pre-1978), proper drainage, attic/crawl access, no exposed wiring, safe water/sewage, structurally sound.","4000.1 II.A.3 / II.D"),
LQ("FHA","Property","What is the FHA flipping rule?","Properties resold within 90 days of the seller's acquisition are ineligible (date of prior deed to date of new contract). Resales between 91–180 days with a price increase over 100% require a second appraisal; exceptions for HUD REO, inheritances, employer relocations and government agencies.","4000.1 II.A.1.b.iv(A)"),
LQ("FHA","Property","Can I buy a condo with FHA?","Only in a HUD-approved project or via Single-Unit Approval (SUA) for units in unapproved but eligible projects (owner-occupancy ≥35%, ≤10% FHA concentration for SUA, financially stable HOA).","4000.1 II.C; FHA Condominium rule (2019)"),
LQ("FHA","Property","Can I buy a manufactured home with FHA?","Yes under Title II if built after 6/15/1976, on a permanent foundation certified by an engineer, taxed as real estate, 400+ sq ft, not moved from a previous site (except dealer). Title I chattel loans exist for homes without land.","4000.1 II.A.8.i / II.D.12"),
LQ("FHA","Property","Does FHA allow accessory dwelling units (ADU) income?","Since ML 2023-17, 75% of the ADU's estimated rent can be used as qualifying income on 1-unit properties (with limits), and ADU rent can be used on 203(k) and new construction with conditions.","ML 2023-17"),
LQ("FHA","Property","What is an FHA 'identity of interest' transaction?","A sale between family members, business partners, or landlord/tenant. LTV is limited to 85% unless an exception applies: family member sale of a principal residence, tenant who has rented for 6+ months, employee of a builder, or a builder's own home sale to an employee.","4000.1 II.A.2.b.ii"),
LQ("FHA","Refinance","What is an FHA Streamline refinance?","A refinance of an existing FHA loan with no appraisal, no income verification (non-credit qualifying) and limited credit review. Requirements: 210 days since closing and 6 payments, a net tangible benefit (≥5% reduction in P&I+MIP for fixed-to-fixed, or ARM-to-fixed rules), and at most one 30-day late in the last 12 months (none in last 6).","4000.1 II.A.8.d"),
LQ("FHA","Refinance","How much cash can I take on an FHA cash-out?","Up to 80% LTV; the property must have been owned and occupied as a primary residence for 12 months (unless inherited) with on-time payments for 12 months; full credit qualifying with an appraisal.","4000.1 II.A.8.d.vi; ML 2019-11"),
LQ("FHA","Refinance","What is an FHA Simple Refinance?","An FHA-to-FHA rate/term refinance with an appraisal and credit qualifying, allowing up to 97.75% LTV and including closing costs in the loan.","4000.1 II.A.8.d.iv"),
LQ("FHA","Occupancy","Can I rent out my FHA home?","After occupying it as your primary residence for at least one year (12 months), yes; FHA allows a second FHA loan later only in limited cases (relocation ≥100 miles, family-size increase with 75% LTV on the old home, vacating a jointly owned property, or non-occupying co-borrower situations).","4000.1 II.A.1.b.iii"),
LQ("FHA","Occupancy","Can I have two FHA loans at once?","Only with an exception: job relocation outside reasonable commuting distance, increase in family size with ≥25% equity in the current home, divorce/vacating a jointly-owned home, or being a non-occupying co-borrower on another FHA loan.","4000.1 II.A.1.b.iii(A)"),
LQ("FHA","Programs","What is the FHA 203(k) renovation loan?","Finances purchase or refinance plus repairs in one loan. Limited 203(k): up to $75,000 of non-structural repairs with no consultant. Standard 203(k): structural work, a HUD consultant, minimum $5,000, contingency reserve 10–20%, up to 6 months of mortgage payments financed if uninhabitable.","4000.1 II.A.8.a; ML 2024-13"),
LQ("FHA","Programs","What is the FHA Energy Efficient Mortgage (EEM)?","Adds the cost of cost-effective energy improvements to the loan above the normal limits based on a home energy assessment.","4000.1 II.A.8.c"),
LQ("FHA","Programs","What is FHA's 203(h) disaster loan?","100% financing for victims of a Presidentially declared disaster whose home was destroyed or damaged, applied for within 1 year of the declaration; can combine with 203(k).","4000.1 II.A.8.b"),
LQ("FHA","Programs","What is Good Neighbor Next Door?","A HUD program selling HUD-owned homes in revitalization areas at 50% off to teachers, law enforcement, firefighters and EMTs who commit to live there 36 months; an FHA loan with $100 down is allowed.","HUD GNND program"),
LQ("FHA","Fees","What fees can FHA borrowers pay?","Reasonable and customary fees: origination, appraisal, credit, title, recording, prepaids, points; there is no longer a 1% origination cap (removed 2010); lenders must not charge 'unallowable' marked-up fees.","4000.1 II.A.6.a.iv"),
LQ("FHA","Process","What is the FHA case number and why does timing matter?","A case number assigned via FHA Connection when the application and property are identified; it fixes the MIP rules and loan limits in effect and starts the appraisal validity (120 days, extendable); a case must be assigned before the appraisal is ordered.","4000.1 II.A.1.a.ii"),
LQ("FHA","Process","What is CAIVRS and does FHA check it?","Yes—borrowers with a delinquent federal debt or prior FHA claim are ineligible until resolved (3 years after an FHA claim is paid).","4000.1 II.A.1.b.ii(A)(10)"),
LQ("FHA","Process","Can non-U.S. citizens get FHA loans?","Lawful permanent residents yes; non-permanent residents were removed from eligibility by ML 2025-09 (effective May 2025)—verify current guidance before quoting.","ML 2025-09"),
LQ("FHA","Comparisons","When is FHA better than conventional?","Scores below ~680 with less than 10% down (MI cost), DTI above 50%, recent credit events (2–3 years), non-occupant co-borrowers at max LTV, or collections that conventional AUS won't accept. Compare with HomeReady/Home Possible first when income is ≤80% AMI.","4000.1; Fannie B5-6"),
LQ("FHA","Comparisons","When is conventional better than FHA?","Scores ~700+ or 10%+ down (MI cancels), condos not FHA-approved, second homes/investment properties, higher loan amounts, or when avoiding life-of-loan MIP.","Fannie B7-1; 4000.1 Appendix 1.0"),
// ===== Conventional =====
LQ("Conventional","Basics","What is a conventional conforming loan?","A mortgage not insured by the government that meets Fannie Mae/Freddie Mac guidelines and loan limits so it can be sold to them. Minimum 3% down (first-time buyers or affordable programs) or 5% standard, 620 score, private MI above 80% LTV that cancels, and pricing adjustments (LLPAs) by score and LTV.","Fannie Selling Guide B2–B5; Freddie Guide 4000–5500"),
LQ("Conventional","Basics","What are the 2026 conforming loan limits?","$832,750 for 1-unit baseline; high-cost areas up to $1,249,125; 2–4 units higher ($1,066,250 / $1,288,850 / $1,601,450 baseline—verify FHFA table).","FHFA 2026 limits"),
LQ("Conventional","Basics","What is the minimum down payment?","3% with Conventional 97/HomeReady/Home Possible/HomeOne (1-unit primary); 5% standard primary; 10% second home; 15% 1-unit investment; 25% 2–4 unit investment; 5% for 2–4 unit primary (2023 change).","Fannie Eligibility Matrix"),
LQ("Conventional","MI","How does private mortgage insurance work and when does it end?","Required above 80% LTV. Options: borrower-paid monthly (cancels at 80% LTV by request with good payment history, automatically at 78% of original value), lender-paid (built into rate, never cancels), single-premium (upfront, can be seller-paid), or split. Cost depends on score, LTV, coverage and DTI.","Homeowners Protection Act; Fannie B7-1"),
LQ("Conventional","MI","Can I cancel PMI early with a new appraisal?","Yes—servicers typically allow cancellation at 80% LTV based on current value after 2 years (75% if less than 2 years), subject to the servicer's appraisal and a good payment history.","Fannie Servicing Guide B-8.1-04"),
LQ("Conventional","Pricing","What are LLPAs?","Loan-level price adjustments: cumulative pricing hits by credit score, LTV, occupancy, property type, cash-out, subordinate financing, and loan size; waived or capped for ≤80% AMI borrowers on HomeReady/Home Possible and for first-time buyers ≤100% AMI (2023 grid).","Fannie LLPA Matrix (2023+)"),
LQ("Conventional","Ratios","What is the maximum DTI for conventional?","DU can approve up to 50% with strong compensating factors; LPA similar; manual underwriting 36% (45% with reserves and higher scores).","Fannie B3-6-02"),
LQ("Conventional","Credit","What is the minimum credit score?","620 for most loans (DU/LPA); manual underwrites per matrix; ARMs 620; no-score borrowers allowed via DU in limited cases (12 months rent history/cash-flow assessment).","Fannie B3-5.1-01"),
LQ("Conventional","Credit","How are scores for two borrowers handled?","Each borrower's representative score is the middle of three (or lower of two); DU now uses the average of the borrowers' representative scores for pricing/eligibility (2022 change), while some lenders still use the lowest.","Fannie B3-5.1-02; DU release notes"),
LQ("Conventional","Credit","Waiting periods after bankruptcy, foreclosure, short sale?","Chapter 7/11: 4 years (2 with extenuating circumstances); Chapter 13: 2 years from discharge or 4 from dismissal; foreclosure: 7 years (3 with extenuating, with LTV/occupancy limits); short sale/DIL: 4 years (2 extenuating); multiple bankruptcies: 5 years.","Fannie B3-5.3-07"),
LQ("Conventional","Credit","Do collections have to be paid on conventional?","1-unit primary: no (DU); 2–4 unit primary, second homes and investment: collections/charge-offs over $5,000 aggregate must be paid. Judgments and liens must be paid before closing.","Fannie B3-5.3-09"),
LQ("Conventional","Credit","How are student loans counted?","Fannie: the documented payment (including IBR if >$0); if $0 or not shown, 1% of the balance (or a fully amortizing payment). Freddie: 0.5% of the balance if no payment shown. Deferred loans are not excluded.","Fannie B3-6-05; Freddie 5401.2"),
LQ("Conventional","Credit","Can I exclude a debt someone else pays?","Yes with 12 months of canceled checks/statements showing the other party (not a co-borrower) paid it; business-paid debts with 12 months business statements and inclusion in cash-flow analysis.","Fannie B3-6-05"),
LQ("Conventional","Income","How is variable income (OT/bonus/commission) treated?","24-month average generally (12 months if DU/LPA accept with justification); declining trends use the lower or current; commission ≥25% formerly required returns—now treated like other variable income.","Fannie B3-3.1-03"),
LQ("Conventional","Income","When can self-employed borrowers use one year of returns?","DU may require only the most recent year when the borrower has been self-employed ≥5 years and shows stable/increasing income; otherwise 2 years (Form 1084 analysis).","Fannie B3-3.2-01"),
LQ("Conventional","Income","How does rental income work on conventional?","Subject 1-unit investment or 2–4 unit: 75% of lease or 1007/1025 rents; Schedule E for existing rentals; landlord history no longer required (2023) but rental income without history is limited to offsetting the subject's PITIA; departure residence lease + deposit.","Fannie B3-3.1-08"),
LQ("Conventional","Income","Does boarder income count?","Only on HomeReady (up to 30% of qualifying income with 12 months history) and HomeStyle; not on standard conventional.","Fannie B3-3.1-09"),
LQ("Conventional","Assets","What counts as acceptable gift funds?","Gifts from relatives, domestic partners, fiancés or guardians; 1-unit primary can be 100% gift; 2–4 units/second homes need 5% own funds if LTV >80%; investment properties no gifts.","Fannie B3-4.3-04"),
LQ("Conventional","Assets","What is a large deposit on conventional?","Any single deposit exceeding 50% of the total monthly qualifying income must be sourced (DU); undocumented portions are excluded from assets.","Fannie B3-4.2-02"),
LQ("Conventional","Assets","How much are reserves?","Per DU; typically none for 1-unit primary, 2 months for second homes, 6 months for investment, plus 2–6% of unpaid balances on other financed properties.","Fannie B3-4.1-01"),
LQ("Conventional","Seller credits","What are the interested-party contribution limits?","Primary/second: 3% (LTV >90%), 6% (75.01–90%), 9% (≤75%); investment 2%. IPCs cover closing costs, prepaids, points, MI premiums and buydowns—never the down payment or borrower debts.","Fannie B3-4.1-02"),
LQ("Conventional","Property","What is value acceptance (appraisal waiver)?","DU/LPA may offer to accept the estimated value without an appraisal based on data; common on refinances and purchases ≤80–90% LTV with prior appraisals in the database.","Fannie B4-1.4-10"),
LQ("Conventional","Property","How are condos reviewed?","Limited review (primary ≤90% LTV; second ≤75%; investment ≤75%) checks basics; full review adds budget/reserves (10%), owner-occupancy, litigation, commercial space, single-entity limits, deferred maintenance/special assessments (2022 rules after Surfside).","Fannie B4-2.2; Lender Letter LL-2021-14"),
LQ("Conventional","Property","Are manufactured homes allowed?","Yes: multi-width on permanent foundations titled as real property; MH Advantage (97% LTV) for homes with site-built features; single-wides with restrictions.","Fannie B5-2"),
LQ("Conventional","Property","Can I buy a mixed-use property?","Yes if residential use predominates, commercial use ≤25% of square footage (Fannie) and the property is a 1-unit primary.","Fannie B2-3-04"),
LQ("Conventional","Property","How many financed properties can I have?","Up to 10 (including the primary) for second-home and investment borrowers, with reserve requirements; no limit for primary-residence loans.","Fannie B2-2-03"),
LQ("Conventional","Refinance","What is a limited cash-out (rate/term) refinance?","Pays off the first mortgage and purchase-money or 12-month-seasoned subordinate liens, plus closing costs, with cash back ≤2% of the loan or $2,000; priced better than cash-out; 97% LTV on 1-unit primary.","Fannie B2-1.3-02"),
LQ("Conventional","Refinance","What are cash-out limits and seasoning?","80% LTV 1-unit primary (75% 2–4 units and second homes/investment, 70% 2–4 investment); 12 months ownership (6 inherited/legally awarded); delayed financing exception for cash purchases within 6 months.","Fannie B2-1.3-03"),
LQ("Conventional","Refinance","What is delayed financing?","A cash-out refinance within 6 months of a cash purchase for up to the purchase price plus costs (within cash-out LTV), with the purchase funds documented and no gift funds used.","Fannie B2-1.3-03"),
LQ("Conventional","Programs","What are HomeReady and Home Possible?","Fannie's and Freddie's 3%-down programs for borrowers at ≤80% of area median income: reduced MI, LLPA waivers, boarder/ADU income, homeownership education, non-occupant co-borrowers allowed.","Fannie B5-6; Freddie 4501"),
LQ("Conventional","Programs","What is HomeOne?","Freddie's 3%-down program for first-time buyers with no income limit (1-unit primary).","Freddie 4605"),
LQ("Conventional","Programs","What is a Conventional 97?","Fannie's standard 97% LTV loan for first-time buyers (at least one borrower) with no income limit on 1-unit primary homes; standard MI and LLPAs.","Fannie B2-1.1-01"),
LQ("Conventional","Programs","What is HomeStyle Renovation?","Fannie's renovation loan financing repairs up to 75% of the as-completed value on primary, second and investment properties, with licensed contractors and draws.","Fannie B5-3.2"),
LQ("Conventional","Programs","What is a high-balance loan?","A conforming loan above the baseline limit up to the county high-cost limit; LTV limits and LLPAs differ (e.g., 90% max 1-unit primary purchase; higher pricing).","Fannie B2-1.5-01"),
LQ("Conventional","Programs","How do conventional ARMs qualify?","5/6 ARM: qualify at the greater of the note rate + 2% or the fully indexed rate; 7/6 and 10/6: at the note rate; SOFR-indexed with 2/1/5 or 5/1/5 caps.","Fannie B3-6-04; B2-1.4-02"),
LQ("Conventional","Programs","What are temporary buydowns on conventional?","Seller/builder/lender/borrower-funded 3-2-1, 2-1 or 1-0 buydowns on fixed-rate (and some ARM) primary/second homes; qualify at the note rate; funds count as IPCs.","Fannie B2-1.5-04"),
LQ("Conventional","Comparisons","Fannie vs Freddie—does it matter?","Yes in edge cases: student-loan payments (Freddie 0.5%), occupying-borrower DTI with non-occupant co-borrowers (Freddie 43% rule), no-score and cash-flow assessment (Freddie LPA AIM), 1-year self-employed (Fannie DU message), rental income without history. Run both AUS.","Fannie/Freddie guides"),
LQ("Conventional","Process","What is a Loan Estimate tolerance?","Under TRID, lender fees and affiliates can't increase (0%), third-party fees from the provider list ≤10% aggregate increase, prepaids/borrower-chosen providers unlimited; overages are cured with lender credits.","Reg Z 1026.19(e)(3)"),
LQ("Conventional","Process","What does 'Approve/Eligible' mean?","DU's recommendation that the loan meets Fannie's credit risk and eligibility; 'Approve/Ineligible' means credit is fine but a guideline (e.g., LTV) is violated; 'Refer' requires manual underwriting.","Fannie B3-2"),
// ===== USDA =====
LQ("USDA","Basics","What is a USDA loan?","A 100%-financing mortgage guaranteed by USDA Rural Development for moderate-income households buying in eligible rural areas; guarantee fee 1% upfront (financed) and 0.35% annual; no down payment; 30-year fixed only.","USDA HB-1-3555 Ch.6–7"),
LQ("USDA","Eligibility","Which areas are eligible?","Areas outside cities over 35,000 (with some grandfathered areas); check the USDA eligibility map by address. Parts of Temecula/Winchester/Menifee outskirts, Hesperia, Pahrump, Queen Creek fringes and many Illinois/Florida towns qualify.","HB-1-3555 Ch.12; USDA eligibility map"),
LQ("USDA","Eligibility","What are the income limits?","Household income (all adults in the home, even non-borrowers) must be ≤115% of area median (around $112k–$130k+ for 1–4 person households in many SoCal counties—verify the county table); deductions for dependents, childcare and disability.","HB-1-3555 Ch.9"),
LQ("USDA","Ratios","What are USDA ratios?","29% front / 41% back; GUS may accept higher; manual files above 41% need compensating factors (660+ score, reserves, stable employment).","HB-1-3555 Ch.11"),
LQ("USDA","Credit","What credit score is needed?","640 for streamlined GUS approvals; below 640 requires manual underwriting with 12 months verified rent and no major derogatory; no-score borrowers use non-traditional credit.","HB-1-3555 Ch.10"),
LQ("USDA","Property","What properties qualify?","Modest, existing or new 1-unit homes (condos/PUDs with approval), no income-producing buildings, not designed for income; new manufactured homes (and existing in pilot states); site value typically ≤30% of total (not a hard rule).","HB-1-3555 Ch.12"),
LQ("USDA","Fees","What are the fees?","1.00% upfront guarantee fee (financed above 100% LTV) and 0.35% annual fee paid monthly; seller may pay up to 6% of costs.","HB-1-3555 Ch.6"),
LQ("USDA","Refinance","Can I refinance a USDA loan?","Yes: streamlined-assist (no appraisal/credit, $50 monthly savings), streamlined, and non-streamlined (appraisal) refinances; no cash-out.","HB-1-3555 Ch.6"),
LQ("USDA","Process","Why do USDA loans take longer?","After lender underwriting, the file goes to the USDA state office for a Conditional Commitment (1–10 business days depending on backlog).","HB-1-3555 Ch.15"),
LQ("USDA","Comparisons","USDA vs FHA?","USDA: $0 down, cheaper fees (0.35% vs 0.55%), but area and income limits and slower; FHA: anywhere, higher income OK, more lenient credit.","HB-1-3555; 4000.1"),
// ===== Jumbo =====
LQ("Jumbo","Basics","What is a jumbo loan?","A loan above the conforming limit (or above the high-cost limit) held by banks or sold to private investors; typically 10–20% down, 700+ scores, 6–12 months reserves, 43–45% DTI, full documentation, and two appraisals over ~$1.5–2M.","Investor guidelines"),
LQ("Jumbo","Basics","How much down do jumbo loans require?","5–10% to ~$1.5M for strong borrowers (740+), 10–20% to $2–3M, 25–30% above; second homes 20–25%, investment 25–35%.","Lender matrices"),
LQ("Jumbo","Income","How is income treated on jumbo?","Full doc 2 years; RSU/stock income with history; asset depletion (assets ÷ 360, some ÷ 240/120); bank-statement options on Non-QM jumbo.","Investor guidelines"),
LQ("Jumbo","Credit","What score and tradelines do jumbos want?","680–760 by LTV; often 3 open tradelines with 24 months, no mortgage lates in 24 months, 7 years from bankruptcy/foreclosure.","Investor guidelines"),
LQ("Jumbo","Property","Why two appraisals?","Investors require two independent appraisals (or appraisal + desk review) above $1.5–2M to validate value; the lower value is used.","Investor guidelines"),
LQ("Jumbo","Strategy","How can I avoid jumbo pricing?","Piggyback 80/10/10 (conforming first + HELOC second), larger down to reach the high-balance limit, or VA jumbo for eligible veterans ($0 down, no MI).","Fannie B2-1.1-04; VA"),
LQ("Jumbo","Strategy","Are jumbo ARMs cheaper?","Often—7/6 and 10/6 ARMs from banks price below 30-year fixed jumbo; good for 5–10 year horizons.","Market pricing"),
LQ("Jumbo","Process","Do jumbo lenders allow gift funds?","Usually yes on primary residences with 5–10% own funds; investment properties typically require all own funds.","Investor guidelines"),
// ===== Non-QM / bank statement =====
LQ("Non-QM","Basics","What is a Non-QM loan?","A mortgage that doesn't meet the Qualified Mortgage rule (e.g., interest-only, DTI >43% without AUS, alternative income documentation) but still satisfies the Ability-to-Repay rule through documentation like bank statements, P&L, 1099s, assets or rents.","Reg Z 1026.43"),
LQ("Non-QM","Bank statement","How does a bank-statement loan work?","12 or 24 months of personal or business statements; qualifying income = average monthly deposits (minus transfers and non-business deposits) × (1 − expense factor, typically 50% or per CPA letter/NAICS) × ownership %. Minimum 2 years self-employed, 620–680 scores, 10–20% down.","Investor matrices (Angel Oak, Deephaven, A&D, Verus)"),
LQ("Non-QM","Bank statement","What disqualifies deposits?","Transfers from your own accounts, loan proceeds, large one-time deposits without support, refunds; more than 3 NSFs in 12 months and declining trends over 20% are red flags.","Investor matrices"),
LQ("Non-QM","Bank statement","Personal vs business statements?","Personal statements: 100% of deposits usually count (must show business income flowing in). Business statements: expense factor applies. Pick the one that yields more income while passing the investor's tests.","Investor matrices"),
LQ("Non-QM","P&L","What is a P&L-only loan?","Qualifies on a CPA/EA-prepared 12–24 month profit and loss statement, with 2–3 months of statements showing deposits that support a percentage of the stated revenue.","Investor matrices"),
LQ("Non-QM","1099","What is a 1099-only loan?","Uses 1–2 years of 1099s with a 10% expense factor (varies) for contractors and commissioned workers without tax returns.","Investor matrices"),
LQ("Non-QM","Asset depletion","How does asset depletion work?","Liquid assets (after down payment and reserves) ÷ a term (often 60, 84, 120 or 360 months) create qualifying income; retirement assets may be counted at a discount; no employment needed.","Investor matrices; Fannie B3-3.1-09 (agency version)"),
LQ("Non-QM","WVOE","What is a WVOE-only loan?","Qualifies W-2 employees using a written verification of employment form plus 2 months of direct-deposit evidence, without pay stubs/W-2s.","Investor matrices"),
LQ("Non-QM","Interest-only","How do interest-only loans qualify?","Borrowers qualify at the fully amortizing payment over the remaining term after the IO period (e.g., 20 years after a 10-year IO), typically 43–50% DTI and 700+ scores.","Reg Z ATR; investor matrices"),
LQ("Non-QM","Credit events","Can I get a loan 1 year after foreclosure?","Yes with 'recent credit event' Non-QM programs at 65–80% LTV, 620–680 scores and 12 months of clean housing history.","Investor matrices"),
LQ("Non-QM","Pricing","Why are Non-QM rates higher and are there prepayment penalties?","No agency guarantee → private capital pricing (+0.75–2.5%); prepayment penalties are allowed only on business-purpose (investment) loans in states that permit them, never on primary residences.","Reg Z 1026.43(g); state law"),
LQ("Non-QM","Strategy","When should I refinance out of Non-QM?","When two years of returns support agency income or when seasoning/credit allows VA/conventional—usually 12–36 months later.","—"),
// ===== DSCR =====
LQ("DSCR","Basics","What is a DSCR loan?","A business-purpose investment loan qualified on the property's rent divided by its payment (PITIA) rather than the borrower's income. DSCR ≥1.0–1.25 at 75–80% LTV; no tax returns; LLC vesting allowed; prepayment penalties common.","Investor matrices (Visio, Kiavi, Lima One, Deephaven)"),
LQ("DSCR","Basics","How is DSCR calculated?","Gross monthly rent (lease or 1007 market rent, lower of unless lease documented) ÷ (principal + interest + taxes + insurance + HOA). Some lenders use interest-only payments for the ratio.","Investor matrices"),
LQ("DSCR","Basics","What if DSCR is below 1.0?","'No-ratio' or sub-1.0 programs exist at lower LTV (60–70%) and higher rates; otherwise lower the loan amount, raise rent (STR), or use IO.","Investor matrices"),
LQ("DSCR","Property","Can I use short-term rental income?","Yes with 12 months of platform statements or AirDNA projections (haircut 20–30%) on many programs; condotels at reduced LTV.","Investor matrices"),
LQ("DSCR","Entity","Can I close in an LLC?","Yes—most DSCR lenders prefer LLC vesting with a personal guaranty; provide articles, operating agreement, EIN and good standing.","Investor matrices"),
LQ("DSCR","Credit","What credit and reserves are needed?","660–700 scores, 0×30 housing history, 6–12 months reserves (3 for small loans), experience tiers affect LTV.","Investor matrices"),
LQ("DSCR","Pricing","What are the prepayment penalty options?","1–5 year step-down (e.g., 5-4-3-2-1) or fixed percentages; shorter/no prepay costs rate; some states restrict.","Investor matrices; state law"),
LQ("DSCR","Refinance","Can I cash out with DSCR?","Yes up to 70–75% LTV after 3–6 months seasoning (some allow purchase-price basis sooner).","Investor matrices"),
LQ("DSCR","Strategy","DSCR vs conventional investment loan?","Conventional: lower rate, personal income/DTI, 10-property cap, no LLC; DSCR: no income, no cap, LLC, prepay, higher rate. Use conventional while you can, DSCR for scale.","Fannie B2-2-03; investor matrices"),
// ===== Foreign national / ITIN =====
LQ("Foreign national","Basics","Can a foreign national buy a U.S. home with financing?","Yes—foreign-national DSCR (investment) or second-home programs with a passport and visa/ESTA, 25–35% down from documented foreign funds, 6–12 months reserves in a U.S. account, no U.S. credit required, closing in a U.S. LLC or individually.","Investor matrices (A&D, Deephaven, Acra, Lima One)"),
LQ("Foreign national","Process","How does a foreign buyer sign documents?","Remote online notarization where state law allows, or at a U.S. embassy/consulate, or with an apostilled foreign notarization; plan 2 weeks for logistics.","State RON laws; Hague Apostille"),
LQ("Foreign national","Tax","What is FIRPTA?","On resale, buyers must withhold 15% of the sales price for foreign sellers unless an exemption/withholding certificate applies; plan with an international-tax CPA at purchase.","IRC §1445"),
LQ("Foreign national","Funds","How are foreign funds documented?","60 days of foreign bank statements (translated), evidence of the wire path into a U.S. account, and OFAC screening; crypto must be liquidated with a trail.","Investor matrices; OFAC"),
LQ("ITIN","Basics","Can I get a mortgage with an ITIN instead of an SSN?","Yes through Non-QM/portfolio ITIN programs: 10–25% down, 660+ or non-traditional credit, 2 years of ITIN tax returns or bank statements, primary or investment.","Investor matrices (Change, Acra, A&D, Citadel)"),
LQ("ITIN","Process","Do ITIN borrowers qualify for FHA or conventional?","No—both require a valid SSN; ITIN loans are portfolio/Non-QM only.","4000.1; Fannie B2-2-02"),
LQ("ITIN","Credit","What if the ITIN has expired?","Renew with the IRS (Form W-7); lenders require a valid ITIN letter.","IRS W-7"),
// ===== Reverse =====
LQ("Reverse","Basics","What is a reverse mortgage (HECM)?","An FHA-insured loan for homeowners 62+ that converts home equity into cash (lump sum, line of credit, tenure/term payments) with no monthly mortgage payment; the balance grows and is repaid when the last borrower leaves the home; non-recourse.","HUD 4000.1 II.B; 12 U.S.C. §1715z-20"),
LQ("Reverse","Basics","How much can I get?","The principal limit depends on the youngest borrower's age, the expected interest rate and the home value up to the 2026 limit of $1,249,125—roughly 35–60% of value; first-year draws limited to 60% of the limit (or mandatory obligations + 10%).","HUD PLF tables; ML 2024-xx limits"),
LQ("Reverse","Basics","Do I keep title?","Yes. You remain the owner and must pay taxes, insurance and HOA, maintain the home, and live there as your primary residence.","HECM program rules"),
LQ("Reverse","Costs","What does a HECM cost?","Upfront MIP 2% of the max claim amount, annual MIP 0.5%, origination fee (2% of first $200k + 1% above, max $6,000), third-party closing costs, and a servicing set-aside in some cases.","12 U.S.C. §1715z-20; 24 CFR 206"),
LQ("Reverse","Eligibility","Is there a credit or income test?","A financial assessment reviews credit history, property charge payment history and residual income; weak results require a Life Expectancy Set-Aside (LESA) for taxes and insurance rather than a denial.","HUD FA Guide (ML 2014-21 as amended)"),
LQ("Reverse","Eligibility","What about a spouse under 62?","An eligible non-borrowing spouse can remain in the home after the borrower's death if conditions are met (identified at origination, continues to occupy, pays charges); principal limit uses the younger spouse's age.","ML 2014-07; 24 CFR 206.55"),
LQ("Reverse","Purchase","What is HECM for Purchase?","Buy a home with a HECM: the borrower brings a down payment (typically 45–60% of price) from documented funds and the HECM covers the rest with no monthly payment; limited seller concessions allowed since 2024.","24 CFR 206.44; ML 2024-15"),
LQ("Reverse","Heirs","What happens to my heirs?","They can keep the home by paying the lesser of the loan balance or 95% of appraised value, sell and keep any equity, or walk away with no liability (non-recourse).","24 CFR 206.125"),
LQ("Reverse","Strategy","Why would a financial planner use a HECM line of credit?","The unused line grows at the loan's rate plus MIP regardless of home value, creating a liquidity buffer that lets retirees avoid selling investments in down years (sequence-of-returns risk) and defer Social Security.","Journal of Financial Planning research (Pfau, Sacks & Sacks)"),
LQ("Reverse","Proprietary","What is a proprietary (jumbo) reverse?","Private reverse mortgages for homes above the HECM limit (to $4M+), sometimes available at 55+, with no MIP and usually a fixed lump sum.","Lender programs (Longbridge Platinum, FAR HomeSafe)"),
LQ("Reverse","Counseling","Is counseling required?","Yes—HUD-approved counseling before application, with a certificate; the lender cannot order the appraisal before counseling.","24 CFR 206.41"),
// ===== HELOC / second liens =====
LQ("HELOC","Basics","HELOC vs HELOAN vs cash-out refinance?","HELOC: variable-rate line with interest-only draw period (10 years) then repayment; HELOAN: fixed-rate lump-sum second; cash-out: replaces the first mortgage. Keep a low first-lien rate with a second; refinance only if the blended rate exceeds the new rate.","Reg Z 1026.40; Calculators → HELOC vs Cash-out"),
LQ("HELOC","Basics","How much can I borrow?","Typically to 85–90% combined LTV on a primary (up to 95% for strong credit), 80% second homes, 70–80% investment, with 640–680+ scores and 43–50% DTI (HELOCs qualified at a fully drawn payment).","Lender guidelines"),
LQ("HELOC","Qualifying","How is a HELOC payment counted in DTI?","At the fully drawn amount (1% or amortizing payment) by most lenders even if you draw less.","Fannie B3-6-05 (for firsts); lender policy"),
LQ("HELOC","Property","Do I need an appraisal?","Many use AVMs or desktop valuations under $250–400k; full appraisals above; condos OK; manufactured homes often excluded.","Lender guidelines"),
LQ("HELOC","Process","Can I get a HELOC on a listed home?","Rarely—most lenders exclude properties listed for sale in the last 6 months; open the HELOC before listing.","Lender guidelines"),
LQ("HELOC","Refinance","What is a subordination?","When you refinance the first mortgage, the HELOC lender must agree to stay in second position; it takes 2–4 weeks and a fee; the combined LTV must fit their rules.","Lender policy"),
LQ("HELOC","Tax","Is HELOC interest deductible?","Only when used to buy, build or substantially improve the home securing it (current law), within the $750k acquisition-debt limit; not for debt consolidation.","IRC §163(h); TCJA"),
LQ("HELOC","Strategy","What is a first-lien HELOC / all-in-one loan?","A HELOC in first position where deposits reduce the daily balance; disciplined borrowers cut interest dramatically; variable rate and requires cash-flow discipline.","Lender programs"),
// ===== Construction / renovation / land =====
LQ("Construction","Basics","What is a construction-to-permanent loan?","One closing covers the land, construction draws and the permanent mortgage; interest-only on draws during the build (often 12 months), then converts to a fixed mortgage; agency (Fannie single-close), FHA OTC and VA OTC versions exist.","Fannie B5-3.1; 4000.1 II.A.8.i; VA Circular 26-18-7"),
LQ("Construction","Builder","What does the lender need from my builder?","License, insurance, references, financial statements, a fixed-price contract, plans/specs, budget, and draw schedule; owner-builders are rarely allowed.","Lender guidelines"),
LQ("Construction","Appraisal","How is a home under construction appraised?","'As-completed' value from plans and specs; the loan is sized on the lower of cost or value; a final inspection/CO is required before conversion.","Fannie B4-1.2-03"),
LQ("Construction","Costs","What costs should I plan for?","Down payment on total cost (0% VA, 3.5% FHA, 5–10% conventional, 20%+ private), 5–10% contingency, interest reserve, builder's risk insurance, permits, and soft costs.","Lender guidelines"),
LQ("Construction","Land","Can I finance just a lot?","Yes with lot loans from banks/credit unions: 20–50% down, 5–15 year terms, higher rates; the lot equity later counts toward the construction loan down payment.","Lender guidelines"),
LQ("Renovation","Basics","Which renovation loans exist?","FHA 203(k) Limited/Standard, Fannie HomeStyle, Freddie CHOICERenovation, VA Alteration & Repair (lender programs), and private fix-and-flip for investors.","4000.1 II.A.8.a; Fannie B5-3.2; Freddie 4607"),
LQ("Renovation","Process","How do draws work?","Funds are escrowed at closing; contractors are paid in stages after inspections; Limited 203(k) allows up to 2 draws (50% at start); HomeStyle up to 5.","4000.1; Fannie B5-3.2"),
LQ("Renovation","Strategy","Can I do the work myself?","FHA 203(k) allows self-help only with proven skills and no labor cost financing; HomeStyle allows 'do-it-yourself' up to 10% of as-completed value for 1-unit primary.","4000.1 II.A.8.a; Fannie B5-3.2-02"),
// ===== Manufactured =====
LQ("Manufactured","Basics","What's the difference between manufactured, modular and mobile homes?","Manufactured: built to the HUD code after 6/15/1976 on a steel chassis; modular: built to local code in sections and treated like site-built; 'mobile' refers to pre-1976 homes, which are not financeable with FHA/VA/agency loans.","HUD code; Fannie B5-2"),
LQ("Manufactured","Financing","Which loans work for manufactured homes?","FHA Title II (96.5%), VA (100%), USDA (new homes), Fannie MH Advantage (97%)/standard (95%), Freddie CHOICEHome, chattel loans (home only) from specialty lenders, and CalVet for homes in parks.","4000.1; Fannie B5-2; VA 26-7 Ch.12"),
LQ("Manufactured","Property","What is an engineer's foundation certification?","A licensed engineer's certificate that the foundation meets HUD's Permanent Foundations Guide (7584)—required for FHA and most lenders; cost $400–$700.","HUD PFGMH 7584"),
LQ("Manufactured","Property","What if the home was moved?","Homes moved from a previous site (other than the dealer lot) are ineligible for FHA/VA/agency financing; chattel lenders may consider.","4000.1 II.A.8.i"),
LQ("Manufactured","Property","Can I buy a manufactured home in a park?","Only with chattel financing (no land), VA leasehold rules (lease > loan term), or CalVet in California; FHA Title I covers home-only loans with limits.","VA 26-7 Ch.12; FHA Title I"),
// ===== DPA / state =====
LQ("DPA","Basics","What is down payment assistance?","Grants or second mortgages (deferred, forgivable or amortizing) from state housing agencies, counties, cities and nonprofits that cover down payment and/or closing costs on FHA, VA, USDA or conventional first mortgages; income/price limits and homebuyer education apply.","State HFA program guides"),
LQ("DPA","California","What does CalHFA offer?","MyHome Assistance (3–3.5% deferred second), CalHFA conventional/FHA firsts, CalPLUS with ZIP, Dream For All shared-appreciation (lottery), and the ADU grant; income limits by county; first-time buyers.","CalHFA program bulletins"),
LQ("DPA","Nevada","What does Nevada offer?","Home Is Possible (up to 4% DPA), HIP for Heroes (veterans/first responders/teachers—lower rate), Home At Last (rural NV), with 640+ scores and income limits.","Nevada Housing Division"),
LQ("DPA","Arizona","What does Arizona offer?","Home Plus (3–5% DPA statewide, FHA/VA/USDA/conventional), Maricopa Home in Five Advantage, Pima Tucson Homebuyer's Solution; 640+ scores; income ≤ ~$130k.","Arizona IDA; Maricopa IDA"),
LQ("DPA","Illinois","What does Illinois offer?","IHDA Access Forgivable (4% up to $6k), Access Deferred (5% up to $7.5k), Access Repayable (10% up to $10k), Opening Doors ($6k for ITIN/all buyers), SmartBuy (student loan payoff up to $40k); 640+ scores.","IHDA program guides"),
LQ("DPA","Florida","What does Florida offer?","Hometown Heroes (up to $35k, 0% deferred, for frontline occupations), FL Assist ($10k deferred), FL HLP ($10k repayable), HFA Preferred/Advantage (reduced MI conventional), Salute Our Soldiers (veterans), county SHIP grants.","Florida Housing"),
LQ("DPA","Process","Why is the DPA rate higher than market?","Agencies set rates to fund the assistance; compare the net benefit over your holding period—sometimes a lender credit beats DPA.","—"),
LQ("DPA","Process","What happens to DPA when I refinance or sell?","Deferred seconds are repaid at sale/refinance; forgivable seconds vest over time (e.g., 10 years); some bond loans carry recapture tax if sold within 9 years with income growth.","State HFA guides; IRC §143(m)"),
// ===== Refinance (general) =====
LQ("Refinance","Basics","When does refinancing make sense?","When monthly savings recoup closing costs before you expect to sell/refinance again (e.g., $6,000 costs ÷ $200 savings = 30 months), or to remove MI, shorten the term, consolidate debt at a lower blended rate, or convert an ARM.","Calculators → Refi Break-even"),
LQ("Refinance","Basics","What is a no-cost refinance?","Closing costs covered by a lender credit at a higher rate; good when you'll refinance again soon or keep the loan a short time.","Reg Z; market"),
LQ("Refinance","Process","Is there a right to cancel?","Yes—3 business days after signing on refinances of a primary residence (rescission); funding occurs after it expires.","Reg Z 1026.23"),
LQ("Refinance","Process","Will I skip a payment?","You skip the usual payment the month after closing because interest is paid in arrears and prepaid at closing; nothing is 'free'.","Lender practice"),
LQ("Refinance","Process","Do I get my escrow balance back?","Yes—the old servicer refunds the escrow balance within 30 days of payoff; the new loan funds a fresh escrow account.","RESPA 1024.34"),
LQ("Refinance","Strategy","Should I refinance to a 15-year?","Only if the payment fits comfortably; a 30-year with extra principal gives the same payoff with flexibility (slightly higher rate).","Calculators → Amortization"),
LQ("Refinance","Strategy","Can I refinance an investment property?","Yes: conventional 75% rate/term, 70–75% cash-out; DSCR alternatives; higher pricing.","Fannie B2-1.3; investor matrices"),
// ===== Credit & process (all programs) =====
LQ("General","Credit","Which credit score do lenders use?","The middle of your three FICO mortgage scores (FICO 2/4/5 classic models today; FICO 10T/VantageScore 4.0 adoption is phasing in for agency loans); for two borrowers, program rules decide (lowest or average).","FHFA credit score initiative; Fannie B3-5.1-02"),
LQ("General","Credit","How much does a 20-point score change matter?","It can move LLPA tiers (e.g., 680→700) and MI rates, often worth 0.25–0.75% in rate or hundreds per year in MI; use a rapid rescore when close to a tier.","Fannie LLPA matrix; MI rate cards"),
LQ("General","Credit","Should I pay off debts before applying?","Pay revolving balances below 30% (utilization), avoid closing old accounts, don't open new credit, and let the LO advise which installment payoffs help DTI (≤10 payments rule).","FICO; Fannie B3-6-05"),
LQ("General","Credit","How long do inquiries affect me?","Mortgage inquiries within 14–45 days (model dependent) count as one; their effect is small and fades within 12 months.","FICO scoring"),
LQ("General","Income","What is the 'two-year rule'?","Lenders want a 2-year history of employment/income to establish stability; gaps over 30–60 days need explanation; education or military service counts toward history.","Fannie B3-3.1-01; 4000.1 II.A.4.c"),
LQ("General","Income","Can I qualify with a new job?","Yes with an offer letter/contract, a start date before closing (or within 90 days for some programs with reserves), and a first pay stub where required.","Fannie B3-3.1-09; 4000.1"),
LQ("General","Income","Do lenders verify income with the IRS?","Usually via 4506-C tax transcripts or third-party verification (The Work Number); mismatches must be explained.","IRS 4506-C; lender policy"),
LQ("General","Assets","Why does the lender need all pages of my bank statements?","To see every deposit and any undisclosed loans/NSFs; missing pages are an automatic condition.","Fannie B3-4.2-01"),
LQ("General","Process","What is TRID and why does timing matter?","The TILA-RESPA Integrated Disclosure rule: Loan Estimate within 3 business days of application, Closing Disclosure at least 3 business days before signing, fee tolerance rules; missing these resets closing dates.","Reg Z 1026.19"),
LQ("General","Process","What is an appraisal gap?","When the appraised value is below the contract price; options: price reduction, cash to cover, seller credit restructure, or cancel under the appraisal contingency (or VA escape clause).","Contract/contingency law"),
LQ("General","Process","What is 'clear to close' vs 'funded'?","CTC means all underwriting conditions are satisfied; funded means the lender wired money after signing and prior-to-funding conditions; recording transfers title.","Industry practice"),
LQ("General","Process","How does an escrow/impound account work?","The lender collects 1/12 of taxes and insurance monthly and pays them when due, with a 2-month cushion; annual analysis adjusts the payment.","RESPA 1024.17"),
LQ("General","Process","What is a rate lock and what if it expires?","A commitment to a rate for a period (30–60 days); expired locks are extended for a fee or relocked at current (worse-of) pricing.","Lender policy"),
LQ("General","Process","What is a lender credit vs discount points?","Points buy a lower rate (1 point = 1% of the loan ≈ 0.25% rate); credits raise the rate to offset costs; choose by how long you'll keep the loan (breakeven).","Calculators → Points vs Credit"),
LQ("General","Process","Can I waive escrow?","Conventional loans ≤80% LTV often allow it (sometimes with a fee); FHA/VA/USDA generally require escrows.","Lender policy; 4000.1"),
LQ("General","Insurance","Why does the lender care about my insurance deductible?","Lenders cap deductibles (often 5% of coverage) and require replacement-cost coverage, the mortgagee clause, and flood insurance in SFHAs.","Fannie B7-3"),
LQ("General","Property","What is a non-warrantable condo?","A project failing agency rules (too much investor ownership, litigation, inadequate reserves, commercial space, single-entity ownership, condotels); financed by portfolio/Non-QM lenders at lower LTVs.","Fannie B4-2.1"),
LQ("General","Property","What's the difference between a condo and a PUD?","Condo: you own the unit's airspace with shared ownership of common elements (stricter project review); PUD: you own the lot and home with an HOA (minimal review).","Fannie B4-2.1-02; B4-2.3"),
LQ("General","Closing","What should I bring to closing?","Government ID (two forms sometimes), cashier's check or wire confirmation for cash to close (verified by phone), and any items on the closer's list; sign in blue/black ink; review the CD against the LE.","TRID; escrow practice"),
LQ("General","After closing","When can I remove a co-borrower?","Only by refinance (or assumption with release on FHA/VA); a quitclaim deed does not remove loan liability.","Contract law; 4000.1; VA 26-7 Ch.5"),
LQ("General","After closing","How do I dispute an escrow shortage?","Request the annual escrow analysis; verify tax bills and insurance premiums; pay the shortage or spread it over 12 months.","RESPA 1024.17"),
LQ("General","After closing","Can my loan be sold?","Yes; servicing transfers are common; terms don't change; you'll get a notice 15 days before and 15 after.","RESPA 1024.33"),
];
/* Partner-facing and first-time-buyer Q&A (used on Programs page and by the Coach) */
LOAN_QA.push(
LQ("Agents & partners","Offers","How do I make a VA or FHA offer competitive?","Pre-underwritten approval (not just pre-qual), short contingency windows (appraisal 10–12 days, loan 17–21 days), appraisal-gap language within the buyer's cash, flexible possession, and a lender call to the listing agent explaining the file. VA appraisals average 7–10 days in SoCal; the 'VA takes forever' myth is outdated.","VA 26-7 Ch.10; NAR 2025 profile"),
LQ("Agents & partners","Offers","Can a seller refuse VA or FHA offers?","Sellers can choose among offers but refusing solely because of financing type exposes them to fair-housing/source-of-income risk in some states (CA Gov. Code §12955 includes 'source of income' for rentals; military status is protected in CA). Educate rather than threaten: show the appraisal and timeline data.","CA FEHA; VA Circular 26-22-11"),
LQ("Agents & partners","Appraisal","What are 'Tidewater' and 'Reconsideration of Value'?","Tidewater: the VA appraiser signals value may come in low and gives 2 business days to submit comps before finalizing. ROV: a formal request after the NOV with better comps. On conventional/FHA, ROV follows the lender's appraisal-review policy (new 2024 ROV rules).","VA 26-7 Ch.10; HUD ML 2024-07; FHFA ROV"),
LQ("Agents & partners","Repairs","What repairs must be fixed before closing?","Government MPR items: safety, security, soundness (peeling paint pre-1978, broken windows, missing handrails, roof leaks, non-working systems, pest damage). Cosmetic items are not required. Conventional allows 'as-is' when the appraiser says no health/safety issues. Repair escrows (holdbacks) are possible for weather-delayed exterior items.","VA 26-7 Ch.12; 4000.1 II.D"),
LQ("Agents & partners","Timeline","How fast can you close?","VA/FHA/conventional purchases: 17–21 days with a complete file and cooperative appraiser; 30 is the comfortable norm; refinances 25–35 days including rescission. Condo reviews, USDA commitments, 203(k) and short sales add time.","Lender SLAs"),
LQ("Agents & partners","Costs","What can the seller pay for the buyer?","VA: all closing costs plus up to 4% concessions (prepaids, funding fee, debt payoff). FHA: 6% of price. Conventional: 3/6/9% by LTV (2% investment). USDA: 6%. Never the down payment (except VA, which has none).","VA 26-7 Ch.8; 4000.1 II.A.4.d.i; Fannie B3-4.1-02"),
LQ("Agents & partners","Credit","What is the quickest way to raise a buyer's score before closing?","Pay revolving balances under 10–30% and run a rapid rescore (3–5 days), remove erroneous collections via disputes with proof, become an authorized user on an old clean card, and avoid new inquiries. Use the Credit section's simulator to pick the cheapest move.","FICO; credit bureau rescore process"),
LQ("Agents & partners","Co-marketing","What co-marketing is legal with a lender?","RESPA Section 8 prohibits paying for referrals. Shared advertising must be split by fair-market value of the ad space; lender-paid open houses, MSAs without real services, and gift cards for referrals are violations. Joint classes and co-branded content with actual cost sharing are fine.","12 U.S.C. §2607; CFPB RESPA FAQs (2020)"),
LQ("Agents & partners","Leads","Which buyers should an agent send to a VA specialist?","Any active-duty, reservist, Guard, veteran or surviving spouse, plus buyers with zero savings, scores 580–660, high DTI, or prior credit events—VA, FHA and DPA options outperform generic pre-approvals.","—"),
LQ("Agents & partners","Assumptions","How do VA/FHA assumptions work for a seller's listing?","A buyer takes over the seller's low-rate loan with lender approval (credit/income qualifying); the buyer covers the equity gap with cash or a second; VA sellers need a substitution of entitlement to restore theirs; processing takes 45–90 days.","VA 26-7 Ch.5; 4000.1 II.A.8.n"),
LQ("First-time buyer","Basics","How much do I really need to buy a home?","Down payment ($0 VA/USDA, 3.5% FHA, 3–5% conventional) plus closing costs (2–3% of price, often covered by seller credits or lender credits) plus a reserve cushion; many buyers close with $5k–$15k out of pocket on a $500k home using credits and DPA.","Calculators → Cash-to-close"),
LQ("First-time buyer","Basics","What is a pre-approval and why does it matter?","A lender's written commitment after reviewing credit, income and assets (ideally with AUS approval); it tells sellers you're real and sets your price ceiling; it lasts 60–120 days and needs refreshing.","Lender practice"),
LQ("First-time buyer","Basics","Should I buy now or wait for rates to drop?","Compare rent vs. a payment on a home you'd keep 5+ years; refinancing later lowers the rate but you can't 'refinance' the price you paid. Use the Rent vs Buy and Refi Break-even calculators; don't time the market with your life.","Calculators"),
LQ("First-time buyer","Process","What does a home inspection cover vs an appraisal?","Inspection: your contractor-style review of the home's condition for your protection (optional, ~$400–600). Appraisal: the lender's valuation and minimum property check. Get both.","—"),
LQ("First-time buyer","Process","What should I avoid doing after I'm pre-approved?","No new credit, no big purchases, no job changes, no large undocumented deposits, no co-signing, no moving money between accounts without a paper trail, no paying off collections without asking your LO first.","Fannie B3-6-02; lender QC"),
LQ("First-time buyer","Costs","What are closing costs made of?","Lender fees (underwriting/processing), third-party fees (appraisal, credit, title, escrow, recording), prepaids (interest, taxes, insurance, HOA), and optional points; shown on the Loan Estimate page 2.","TRID Reg Z 1026.37"),
LQ("First-time buyer","Costs","Why did my payment go up after the first year?","Escrow analysis: property taxes reassess after purchase (CA Prop 13 sets value at the price) and insurance renews higher; the servicer recalculates monthly escrow plus any shortage.","RESPA 1024.17; CA Prop 13"),
LQ("First-time buyer","Programs","Which first-time buyer programs exist?","Conventional 97/HomeReady/Home Possible/HomeOne, FHA, VA/USDA ($0 down), state DPA (CalHFA, NV HIP, AZ Home Plus, IHDA, FL Hometown Heroes), employer-assisted housing, MCC tax credits where offered, and Good Neighbor Next Door.","Program guides"),
LQ("First-time buyer","Tax","What tax benefits come with owning?","Mortgage interest (on up to $750k of acquisition debt), property taxes (within the SALT cap), PMI/MIP premiums (restored for 2026 with phase-out), points in the year paid on a purchase, and the $250k/$500k capital gains exclusion after 2 years.","IRC §163(h), §164, §121"),
LQ("First-time buyer","Equity","What is PITI and PITIA?","Principal, Interest, Taxes, Insurance (+ Association dues); it's the full housing payment lenders use for DTI, not just P&I.","Fannie B3-6-03"),
);
